// ── Shared components ──
function Label({children,style}){return <span style={{fontFamily:pro,fontSize:11,fontWeight:700,letterSpacing:kL,textTransform:"uppercase",color:dm,...style}}>{children}</span>}

function Badge({status}){
  const m={active:{bg:dimSm,color:P.smeraldo,l:"Attivo"},invited:{bg:dimGh,color:"#5BA8B0",l:"Invitato"},paused:{bg:P.cenere,color:mt,l:"Pausa"}};
  const s=m[status]||m.active;
  return <span style={{display:"inline-flex",alignItems:"center",gap:5,padding:"4px 11px",borderRadius:99,background:s.bg,color:s.color,fontFamily:pro,fontSize:11,fontWeight:700,letterSpacing:"0.05em",textTransform:"uppercase"}}>
    <span style={{width:6,height:6,borderRadius:"50%",background:s.color}}/>{s.l}
  </span>;
}

function ProgressBar({current,max}){
  const pct=max>0?Math.min((current/max)*100,100):0;
  const color=pct>80?P.corallo:pct>50?P.miele:P.smeraldo;
  return <div style={{display:"flex",alignItems:"center",gap:10}}>
    <div style={{flex:1,height:5,background:border,borderRadius:99,overflow:"hidden"}}>
      <div style={{width:`${pct}%`,height:"100%",background:color,borderRadius:99,transition:"width 0.5s ease"}}/>
    </div>
    <span style={{fontFamily:mono,fontSize:12,color:dm,minWidth:34,textAlign:"right"}}>{Math.round(pct)}%</span>
  </div>;
}

function NavItem({label,active,onClick,count,icon:Icon}){
  const [h,setH]=useState(false);
  return <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{
    fontFamily:pro,fontSize:16,fontWeight:500,letterSpacing:k,
    color:active?P.nero:h?P.inchiostro:mt,background:active?h?"#d4f04d":P.lime:h?P.avena:"transparent",
    border:"none",borderRadius:12,padding:"10px 14px",cursor:"pointer",
    width:"100%",textAlign:"left",display:"flex",alignItems:"center",justifyContent:"space-between",
    transition:"all 0.15s",
  }}>
    <span style={{display:"flex",alignItems:"center",gap:8}}>{Icon&&<Icon size={18} strokeWidth={active?2.5:2}/>}{label}</span>
    {count!=null&&<span style={{fontFamily:mono,fontSize:12,color:active?P.nero:dm,background:active?"rgba(15,15,15,0.08)":"rgba(0,0,0,0.04)",padding:"2px 8px",borderRadius:6}}>{count}</span>}
  </button>;
}

function ChartTip({active,payload,label}){
  if(!active||!payload?.length)return null;
  return <div style={{background:P.gesso,borderRadius:12,padding:"10px 14px",border:`1px solid ${border}`,boxShadow:"0 8px 24px rgba(40,40,40,0.08)"}}>
    <div style={{fontFamily:pro,fontSize:11,fontWeight:700,letterSpacing:kL,textTransform:"uppercase",color:dm,marginBottom:4}}>{label}</div>
    <div style={{fontFamily:fono,fontSize:18,fontWeight:700,letterSpacing:kS,color:P.inchiostro}}>€{payload[0].value.toLocaleString("it-IT")}</div>
  </div>;
}

function Donut({active,total}){
  const pct=total>0?active/total:0;
  const r=44,stroke=12,cx=56,cy=56,sz=112;
  const circ=2*Math.PI*r;
  const filled=circ*pct;
  const gap=circ-filled;
  return <div style={{position:"relative",width:sz,height:sz,flexShrink:0}}>
    <svg width={sz} height={sz} viewBox={`0 0 ${sz} ${sz}`}>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={border} strokeWidth={stroke}/>
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={P.smeraldo} strokeWidth={stroke}
        strokeDasharray={`${filled} ${gap}`}
        strokeDashoffset={circ*0.25}
        strokeLinecap="round"
        style={{transition:"stroke-dasharray 0.5s ease"}}/>
    </svg>
    <div style={{position:"absolute",top:0,left:0,width:sz,height:sz,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",pointerEvents:"none"}}>
      <span style={{fontFamily:fono,fontSize:24,fontWeight:700,color:P.inchiostro,lineHeight:1,letterSpacing:kM}}>{active}</span>
      <span style={{fontFamily:pro,fontSize:10,fontWeight:700,color:dm,letterSpacing:"0.08em",textTransform:"uppercase",marginTop:3}}>su {total}</span>
    </div>
  </div>;
}

function PageBtn({children,active,onClick}){
  const [h,setH]=useState(false);
  return <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{fontFamily:pro,fontSize:14,fontWeight:500,letterSpacing:k,width:36,height:36,borderRadius:10,background:active?h?"#d4f04d":P.lime:h?P.avena:P.gesso,color:active?P.nero:mt,border:active?"1px solid transparent":`1px solid ${border}`,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.15s",boxSizing:"border-box"}}>{children}</button>;
}

function Btn({children,onClick,variant="lime",style:sx,flex}){
  const [h,setH]=useState(false);
  const variants={
    lime:{bg:h?"#d4f04d":P.lime,color:P.nero,border:"1px solid transparent",fontWeight:500},
    nero:{bg:h?"#2a2a2a":P.nero,color:P.gesso,border:"1px solid transparent",fontWeight:500},
    ghost:{bg:h?P.avena:P.gesso,color:h?P.inchiostro:mt,border:`1px solid ${h?dm:border}`,fontWeight:500},
    danger:{bg:h?"rgba(244,103,46,0.18)":dimCo,color:P.corallo,border:"1px solid transparent",fontWeight:500},
    secondary:{bg:h?P.cenere:P.avena,color:P.inchiostro,border:`1px solid ${h?dm:border}`,fontWeight:500},
    ghiaccio:{bg:h?P.avena:P.ghiaccio,color:h?P.inchiostro:mt,border:`1px solid ${h?dm:"rgba(15,15,15,0.1)"}`,fontWeight:500},
    link:{bg:"transparent",color:h?P.inchiostro:mt,border:"1px solid transparent",fontWeight:500},
  };
  const v=variants[variant]||variants.lime;
  return <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{
    fontFamily:pro,fontSize:16,letterSpacing:k,
    background:v.bg,color:v.color,border:v.border,fontWeight:v.fontWeight,
    borderRadius:12,padding:"10px 22px",cursor:"pointer",
    display:"flex",alignItems:"center",justifyContent:"center",gap:6,
    transition:"all 0.15s",boxSizing:"border-box",
    flex:flex?1:undefined,
    ...sx,
  }}>{children}</button>;
}

function Card({children,style,accent}){
  return <div style={{background:accent||P.gesso,borderRadius:18,padding:"22px 24px",border:accent?"none":`1px solid ${border}`,position:"relative",overflow:"hidden",...style}}>
    {accent&&<><div style={{position:"absolute",top:-25,right:-25,width:90,height:90,borderRadius:"50%",border:"2px solid rgba(15,15,15,0.05)"}}/><div style={{position:"absolute",bottom:-15,left:-15,width:60,height:60,borderRadius:"50%",border:"2px solid rgba(15,15,15,0.04)"}}/></>}
    {children}
  </div>;
}

function StatCard({label,value,sub,accent,tag}){
  const onColor=!!accent;
  return <Card accent={accent}>
    <Label style={{color:onColor?"rgba(15,15,15,0.4)":dm}}>{label}</Label>
    <div style={{fontFamily:fono,fontSize:34,fontWeight:700,letterSpacing:kT,marginTop:10,lineHeight:1,color:onColor?P.nero:P.inchiostro}}>{value}</div>
    <div style={{display:"flex",alignItems:"center",gap:8,marginTop:8}}>
      <span style={{fontFamily:pro,fontSize:16,color:onColor?"rgba(15,15,15,0.5)":mt}}>{sub}</span>
      {tag&&<span style={{fontFamily:pro,fontSize:11,fontWeight:700,padding:"2px 8px",borderRadius:6,background:onColor?"rgba(15,15,15,0.08)":dimSm,color:onColor?P.nero:P.smeraldo}}>{tag}</span>}
    </div>
  </Card>;
}

// Derive extra fields for employee detail
function empExtra(e){
  const names=e.name.split(" ");
  const firstName=names[0];
  const lastName=names.slice(1).join(" ");
  // Simulate deterministic fields from id
  const seed=e.id;
  const grossSalary=Math.round(e.salary*1.38*13/100)*100;
  const fixedSalary=e.salary;
  const cf=`${lastName.substring(0,3).toUpperCase()}${firstName.substring(0,3).toUpperCase()}${70+seed%30}${"ABCDEHLMPRST"[seed%12]}${10+seed%20}X${100+seed%900}${"ABCDEFGHIJKLMNOPQRSTUVWXYZ"[seed%26]}`;
  const years=1+(seed*7)%12;
  const contracts=["Indeterminato","Determinato","Apprendistato","Somministrazione"];
  const contract=contracts[seed%4];
  const ibanReal=`IT${40+seed%60}X${("0000"+((seed*13)%99999)).slice(-5)}${("0000000000"+((seed*7919)%9999999999)).slice(-10)}${seed%100}`;
  const ibanVirtual=`IT${50+seed%50}V${("0000"+((seed*17)%99999)).slice(-5)}${("0000000000"+((seed*6173)%9999999999)).slice(-10)}${seed%100}`;
  return {firstName,lastName,grossSalary,fixedSalary,cf,years,contract,ibanReal,ibanVirtual};
}

